INSERT INTO listening_lesson (id, lesson_no, title, audio_key, duration_ms, sort_order) VALUES ('listen-09', 9, '第9課 听力训练', 'listening/listening-lesson-09.mp3', 167462, 0);
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn09-s1', 'listen-09', 1, 'text', '听录音，根据录音中的内容仿照例子写下相应的数字。', 10190, 99799, '今日は7月1日です。', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn09-s1-q1', 'lsn09-s1', 1, '中村さんのお誕生日は＿＿月＿＿日です。', '[]'::jsonb, '11月3日');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn09-s1-q2', 'lsn09-s1', 2, '日本語の試験は来週の＿＿曜日です。', '[]'::jsonb, '火|火曜日|火曜');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn09-s1-q3', 'lsn09-s1', 3, 'マイケルさんのお誕生日は＿＿月＿＿日です。', '[]'::jsonb, '5月20日');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn09-s1-q4', 'lsn09-s1', 4, '日本語の授業は＿＿曜日と＿＿曜日です。', '[]'::jsonb, '水・金|水と金|水、金|水金|水曜日と金曜日|水曜日、金曜日|水曜日金曜日');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l1', 'lsn09-s1', 1, 'A', 10490, 16772, '今日は何月何日ですか。', 'A：今天几月几日？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l2', 'lsn09-s1', 2, 'B', 16773, 18986, '7月1日です。', 'B：7月1日。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l3', 'lsn09-s1', 3, 'A', 26257, 32072, '中村さんは何座ですか。', 'A：中村是什么星座？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l4', 'lsn09-s1', 4, 'B', 32073, 33351, '蠍座です。', 'B：天蝎座。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l5', 'lsn09-s1', 5, 'A', 34292, 38908, 'え？蠍座ですか。じゃ、お誕生日は、11月？', 'A：诶？天蝎座？那你的生日是11月？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l6', 'lsn09-s1', 6, 'B', 40269, 41559, 'はい、11月3日です。', 'B：是的，11月3日。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l7', 'lsn09-s1', 7, 'A', 48190, 53671, '日本語の試験は来週ですか。', 'A：日语考试是下周吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l8', 'lsn09-s1', 8, 'B', 54231, 57195, 'はい、そうですよ。来週の火曜日です。', 'B：是的。下周二。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l9', 'lsn09-s1', 9, 'A', 63890, 70566, 'マイケルさんのお誕生日パーティーはいつですか。', 'A：迈克尔的生日派对是什么时候？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l10', 'lsn09-s1', 10, 'B', 71208, 74147, 'ええと、今は５月ですか。', 'B：我想想，现在是5月吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l11', 'lsn09-s1', 11, 'A', 74148, 76265, 'いいえ、4月です。', 'A：不，是4月。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l12', 'lsn09-s1', 12, 'B', 77291, 79555, 'じゃ、来月の20日ですね。', 'B：那就是下个月20号了。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l13', 'lsn09-s1', 13, 'A', 86290, 92482, '今日は日本語の授業がありますか。', 'A：今天有日语课吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s1-l14', 'lsn09-s1', 14, 'B', 92483, 99099, 'いいえ、ありません。日本語の授業は水曜日と金曜日だけですから。', 'B：没有。日语课只有周三和周五。');
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn09-s2', 'listen-09', 2, 'choice', '听录音，根据录音中的内容，将正确答案填在括号中。背景：以下是小王的日记。', 114443, 161209, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn09-s2-q1', 'lsn09-s2', 1, '日本語の試験はいつでしたか。', '[{"key":"a","text":"昨日でした"},{"key":"b","text":"先週でした"},{"key":"c","text":"日曜日でした"}]'::jsonb, 'a');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn09-s2-q2', 'lsn09-s2', 2, '王さんの日本語はどうですか。', '[{"key":"a","text":"あまり上手ではありません。"},{"key":"b","text":"上手です。"}]'::jsonb, 'a');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn09-s2-q3', 'lsn09-s2', 3, '日本人の友達は何人いますか。', '[{"key":"a","text":"ひとり"},{"key":"b","text":"ふたり"},{"key":"c","text":"さんにん"}]'::jsonb, 'b');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn09-s2-q4', 'lsn09-s2', 4, '王さんの留学生活はどうですか。', '[{"key":"a","text":"あまり楽しくありません。"},{"key":"b","text":"とても楽しいです。"}]'::jsonb, 'b');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s2-l1', 'lsn09-s2', 1, '王', 114743, 120848, '昨日は日本語の試験でした。', '小王：昨天是日语考试。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s2-l2', 'lsn09-s2', 2, '王', 121048, 130108, '私は去年、中国から来ました。今、大学２年生です。', '小王：我去年从中国来。现在是大学二年级。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s2-l3', 'lsn09-s2', 3, '王', 131573, 137657, '日本語があまり上手ではありません。でも、日本語の勉強が好きです。', '小王：日语还不太好。但我喜欢学日语。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s2-l4', 'lsn09-s2', 4, '王', 139279, 145898, '私には友達が３人います。日本人の友達は２人で、それから、イギリス人の友達は１人います。', '小王：我有三个朋友。日本朋友两个，还有一位英国朋友。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s2-l5', 'lsn09-s2', 5, '王', 145899, 153057, 'みんな大学のクラスメートで、とてもやさしいです。', '小王：大家都是大学的同学，人很好。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn09-s2-l6', 'lsn09-s2', 6, '王', 153347, 161209, 'みんなのおかげで、私の留学生活はとても楽しいです。', '小王：多亏了大家，我的留学生活非常愉快。');
